#!/usr/bin/env python3
"""Build the original Sendzad email library. Development only; no runtime Python dependency."""
from pathlib import Path
import json,re
from html import escape

ROOT = Path(__file__).resolve().parents[1]
(ROOT/'private/resources').mkdir(parents=True,exist_ok=True)
(ROOT/'public/assets').mkdir(parents=True,exist_ok=True)
FONT = 'Arial,Helvetica,sans-serif'
INK = '#172d37'
MUTED = '#51616b'
CSS = '''html,body{margin:0!important;padding:0!important;width:100%!important}body{-webkit-text-size-adjust:100%;-ms-text-size-adjust:100%}table{border-collapse:collapse;mso-table-lspace:0pt;mso-table-rspace:0pt}img{border:0;outline:none;text-decoration:none;max-width:100%;height:auto}a{overflow-wrap:anywhere}td{word-break:normal}.tz-preheader{display:none!important;max-height:0!important;overflow:hidden!important;mso-hide:all!important}@media only screen and (max-width:640px){.tz-container{width:100%!important;max-width:100%!important}.tz-pad{padding-left:22px!important;padding-right:22px!important}.tz-stack{display:block!important;width:100%!important;max-width:100%!important;box-sizing:border-box!important}.tz-title{font-size:34px!important;line-height:1.15!important}.tz-small-title{font-size:26px!important}.tz-column{padding-left:0!important;padding-right:0!important;padding-bottom:20px!important}.tz-outer{padding:0!important}.tz-mobile-left{text-align:left!important}.tz-utility{font-size:12px!important}.tz-mobile-hide{display:none!important}}'''
CLASSES = ['tz-container','tz-pad','tz-stack','tz-title','tz-small-title','tz-column','tz-outer','tz-mobile-left','tz-utility','tz-mobile-hide','tz-preheader']

def table(content, extra='', style=''):
    return f'<table role="presentation" width="100%" border="0" cellpadding="0" cellspacing="0" {extra} style="border-collapse:collapse;{style}">{content}</table>'
def tr(content): return '<tr>'+content+'</tr>'
def td(content, style='', extra=''): return f'<td {extra} style="{style}">{content}</td>'
def p(text, color=MUTED, size=16, margin='0 0 18px'):
    return f'<p style="margin:{margin};font-family:{FONT};font-size:{size}px;line-height:1.7;color:{color}">{text}</p>'
def h(text, level=2, color=INK, size=26):
    return f'<h{level} class="'+('tz-title' if level==1 else 'tz-small-title')+f'" style="margin:0 0 18px;font-family:{FONT};font-size:{size}px;line-height:1.18;letter-spacing:-1px;font-weight:700;color:{color}">{text}</h{level}>'
def eyebrow(text, color='#426963'):
    text=re.sub(r'\{\{([A-Z_]+)\}\}',lambda m:'{{'+m[1].lower()+'}}',text.upper())
    return f'<p style="margin:0 0 18px;font-family:{FONT};font-size:11px;font-weight:700;letter-spacing:2px;line-height:1.5;color:{color}">{text}</p>'
def button(label='Explore more', url='{{website_url}}', color='#183f38', text='#ffffff'):
    return f'<table role="presentation" border="0" cellpadding="0" cellspacing="0" style="border-collapse:separate"><tr><td align="center" bgcolor="{color}" style="background-color:{color};border-radius:5px;border:1px solid {color};padding:15px 24px"><a href="{url}" style="font-family:{FONT};font-size:15px;line-height:1.2;font-weight:700;color:{text};text-decoration:none;display:inline-block">{label}</a></td></tr></table>'
def link(label, url='https://example.com/replace/link', color='#175f50'):
    return f'<a href="{url}" style="font-family:{FONT};font-size:15px;line-height:1.7;font-weight:700;color:{color};text-decoration:underline">{label} &rarr;</a>'
def section(content, bg='#ffffff', pad='32px 40px', block='text'):
    return table(tr(td(content, f'padding:{pad};background-color:{bg}', 'class="tz-pad"')), f'data-tz-block="{block}"')
def rule(): return table(tr(td('', 'height:1px;background-color:#dce4e2;font-size:1px;line-height:1px','height="1"')), 'data-tz-block="divider"')
def columns(items, bg='#ffffff', block='features'):
    n=len(items)
    cells=''.join(td(x, f'vertical-align:top;width:{100/n:.3f}%;padding:0 10px',f'width="{int(100/n)}%" valign="top" class="tz-stack tz-column"') for x in items)
    return section(table(tr(cells)), bg, '26px 30px', block)
def feature(num,title,body,color='#175f50'):
    return eyebrow(num,color)+h(title,3,INK,20)+p(body,size=14,margin='0')
def hero(label,title,body,cta,url='{{website_url}}',bg='#173e38',ink='#ffffff',accent='#c6e7b4'):
    return section(eyebrow(label,accent)+h(title,1,ink,44)+p(body,ink,17)+button(cta,url,accent,'#17332d'),bg,'40px 40px','hero')
def banner(title,body,cta,url='{{website_url}}',bg='#eef4f1',color='#173e38'):
    return section(h(title,2,color,28)+p(body)+button(cta,url,color),bg,'30px 40px','cta')
PHOTOS=json.loads((ROOT/'scripts/photo-sources.json').read_text())['photos']
def photo(key='workspace',width=560,height=280):
    item=PHOTOS[key]
    url=f"https://images.unsplash.com/{item['photo']}?auto=format&fit=crop&fm=jpg&w={width*2}&h={height*2}&q=75"
    return f'<img src="{escape(url,quote=True)}" alt="{escape(item["alt"],quote=True)}" width="{width}" height="{height}" data-sz-image="stock" style="display:block;width:100%;max-width:{width}px;height:auto;border:0;border-radius:4px">'
def image_section(key='workspace'):
    return section(photo(key),pad='24px 40px 8px',block='photograph')

def product(title='[Product name]', desc='[One clear product benefit]', price='[Price]', bg='#edf2ee',category='PRODUCT 01'):
    keys=['headphones','flowers','sneakers','workspace']
    digits=''.join(c for c in category if c.isdigit())
    key=keys[(max(1,int(digits or '1'))-1)%len(keys)]
    visual=photo(key,240,180)
    return visual+'<div style="height:18px;line-height:18px;font-size:1px">&nbsp;</div>'+h(title,3,INK,20)+p(desc,size=14)+p(price,INK,18)+link('View product','https://example.com/replace/product')
HEADER = table(tr(td('<strong style="font-family:Arial,Helvetica,sans-serif;font-size:24px;letter-spacing:-1px;color:#173e38">{{brand_name}}</strong>','padding:27px 0')+td('<a href="{{website_url}}" style="font-family:Arial,Helvetica,sans-serif;font-size:12px;color:#51616b;text-decoration:none">Visit website &rarr;</a>','text-align:right;padding:27px 0','align="right" class="tz-utility"')), 'data-tz-header="standard"')
FOOTER = table(tr(td(p('{{brand_name}}',INK,15)+p('{{postal_address}}',MUTED,12)+p('{{permission_reminder}}',MUTED,12)+'<a href="{{unsubscribe_url}}" style="font-family:Arial,Helvetica,sans-serif;font-size:13px;color:#34594f;text-decoration:underline">Unsubscribe</a>'+p('&copy; {{year}} {{brand_name}}. All rights reserved.',MUTED,12,'18px 0 0'),'padding:28px 0;border-top:1px solid #dce4e2')), 'data-tz-footer="standard"')

def wrap(content):
    shell=table(tr(td(HEADER,'padding:0 40px','class="tz-pad"'))+tr(td(content,'','data-tz-content="main"'))+tr(td(FOOTER,'padding:0 40px;background-color:#f8faf9','class="tz-pad"')), 'width="640" class="tz-container"', 'width:100%;max-width:640px;background-color:#ffffff')
    # table() has a default width; the container has one authoritative width attribute.
    shell=shell.replace('width="100%" border="0" cellpadding="0" cellspacing="0" width="640"','width="640" border="0" cellpadding="0" cellspacing="0"')
    body='<div data-tz-preheader="standard" class="tz-preheader" style="display:none;max-height:0;overflow:hidden">{{preheader}}</div>'+table(tr(td(shell,'padding:24px 0','align="center" class="tz-outer"')),style='background-color:#edf2f0')
    return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{brand_name}}</title><style>'+CSS+'</style></head><body style="margin:0;padding:0;background-color:#edf2f0">'+body+'</body></html>'

def intro(body): return section(p('Hi {{first_name}},',INK)+p(body))
TEMPLATES=[]
def add(id,name,category,subject,preheader,description,content,color='#173e38',collection='Business',edit=None):
    picture={'welcome':'workspace','newsletter':'workspace','offer':'headphones','product':'headphones','event':'workspace','announcement':'workspace','reengage':'flowers','seasonal':'flowers','thanks':'flowers'}.get(id,'workspace')
    if '<img ' not in content:content=image_section(picture)+content
    notes=edit or ['Review the copy and destination links.']
    notes=[n.replace('Add approved images or remove placeholder panels.','Review the photographs against the products you offer.').replace('Add correct listing links and images.','Review listing links and replace any unrelated stock photographs.').replace('Replace or remove the labelled image placeholder panels.','Review or replace the illustrative stock photographs.') for n in notes]
    notes.append('Stock photographs are illustrative. Check that they match your message and products.')
    TEMPLATES.append(dict(id=id,name=name,category=category,collection=collection,subject=subject,preheader=preheader,description=description,color=color,html=wrap(content),edit_before_send=notes,version=3))

