payload=dict(version='3.0.0',width=640,css=CSS,classes=CLASSES,header=HEADER,footer=FOOTER,templates=TEMPLATES,blocks=BLOCKS)
(ROOT/'private/resources/email-templates.json').write_text(json.dumps(payload,separators=(',',':'))+'\n')
layout={k:v for k,v in payload.items() if k not in ['templates','blocks']}
(ROOT/'private/resources/email-layout.json').write_text(json.dumps(layout,separators=(',',':'))+'\n')
helper=(ROOT/'scripts/template-runtime.js').read_text()
cat='window.SendzadTemplateCatalog='+json.dumps({'templates':TEMPLATES,'blocks':BLOCKS},separators=(',',':'))+';\n'
import hashlib
fingerprint=hashlib.sha256(cat.encode()).hexdigest()[:12]
layout['catalogFile']='template-catalog.'+fingerprint+'.js'
for old in (ROOT/'public/assets').glob('template-catalog.*.js'):old.unlink()
(ROOT/'public/assets'/layout['catalogFile']).write_text(cat)
(ROOT/'public/assets/templates.js').write_text('/* Generated; edit scripts/build_templates.py and template-runtime.js. */\n(()=>{\nconst catalog='+json.dumps(layout,separators=(',',':'))+';\n'+helper+'\n})();\n')
print('Built',len(TEMPLATES),'templates and',len(BLOCKS),'blocks; lazy catalog',fingerprint)
